1	import { readJsonFile, type TargetConfiguration } from '@nx/devkit';
2	import { existsSync } from 'node:fs';
3	import { extname, isAbsolute, relative, resolve } from 'node:path';
4	import { type PackageManagerCommands } from 'nx/src/utils/package-manager';
5	import { join } from 'path';
6	import { type ParsedCommandLine } from 'typescript';
7	import picomatch = require('picomatch');
8	
9	export type ExtendedConfigFile = {
10	  filePath: string;
11	  externalPackage?: string;
12	};
13	export type ParsedTsconfigData = Pick<
14	  ParsedCommandLine,
15	  'options' | 'projectReferences' | 'raw'
16	> & {
17	  extendedConfigFiles: ExtendedConfigFile[];
18	};
