20	/**
21	 * Allow uses that use incremental builds to run `nx watch-deps` to continuously build all dependencies.
22	 */
23	export function addBuildAndWatchDepsTargets(
24	  workspaceRoot: string,
25	  projectRoot: string,
26	  targets: Record<string, TargetConfiguration>,
27	  options: { buildDepsTargetName?: string; watchDepsTargetName?: string },
28	  pmc: PackageManagerCommands
29	): void {
30	  let projectName: string;
31	
32	  const projectJsonPath = join(workspaceRoot, projectRoot, 'project.json');
33	  const packageJsonPath = join(workspaceRoot, projectRoot, 'package.json');
34	
35	  if (existsSync(projectJsonPath)) {
36	    const projectJson = readJsonFile(projectJsonPath);
37	    projectName = projectJson.name;
38	  } else if (existsSync(packageJsonPath)) {
39	    const packageJson = readJsonFile(packageJsonPath);
40	    projectName = packageJson.nx?.name ?? packageJson.name;
41	  }
42	
43	  if (!projectName) return;
44	
45	  if (projectName) {
46	    const buildDepsTargetName = options.buildDepsTargetName ?? 'build-deps';
47	    targets[buildDepsTargetName] = {
48	      dependsOn: ['^build'],
49	    };
50	    targets[options.watchDepsTargetName ?? 'watch-deps'] = {
51	      continuous: true,
52	      dependsOn: [buildDepsTargetName],
53	      command: `${pmc.exec} nx watch --projects ${projectName} --includeDependentProjects -- ${pmc.exec} nx ${buildDepsTargetName} ${projectName}`,
54	    };
55	  }
56	}
57	
58	export function isValidPackageJsonBuildConfig(
59	  tsConfig: ParsedTsconfigData,
60	  workspaceRoot: string,
61	  projectRoot: string
62	): boolean {
63	  const resolvedProjectPath = isAbsolute(projectRoot)
64	    ? relative(workspaceRoot, projectRoot)
65	    : projectRoot;
66	  const packageJsonPath = join(
67	    workspaceRoot,
68	    resolvedProjectPath,
69	    'package.json'
70	  );
71	  if (!existsSync(packageJsonPath)) {
72	    // If the package.json file does not exist.
73	    // Assume it's valid because it would be using `project.json` instead.
74	    return true;
75	  }
76	  const packageJson = readJsonFile(packageJsonPath);
77	
78	  const projectAbsolutePath = resolve(workspaceRoot, resolvedProjectPath);
79	
80	  // Handle outFile first (has precedence over outDir)
81	  if (tsConfig.options.outFile) {
82	    const outFile = resolve(
83	      workspaceRoot,
84	      resolvedProjectPath,
85	      tsConfig.options.outFile
86	    );
87	    const relativeToProject = relative(projectAbsolutePath, outFile);
88	
89	    // If outFile is outside project root: buildable
90	    if (relativeToProject.startsWith('..')) {
91	      return true;
92	    }
93	    // If outFile is inside project root: check if entry points point to outFile
94	
95	    const isPathSourceFile = (path: string): boolean => {
96	      const normalizedPath = isAbsolute(path)
97	        ? resolve(workspaceRoot, path.startsWith('/') ? path.slice(1) : path)
98	        : resolve(workspaceRoot, resolvedProjectPath, path);
99	
100	      // For outFile case, check if path points to the specific outFile
101	      return normalizedPath === outFile;
102	    };
103	
104	    // Check if any entry points match the outFile
105	    const exports = packageJson?.exports;
106	    if (exports) {
107	      if (typeof exports === 'string') {
108	        return !isPathSourceFile(exports);
109	      }
110	      if (typeof exports === 'object' && '.' in exports) {
111	        const dotExport = exports['.'];
112	        if (typeof dotExport === 'string') {
113	          return !isPathSourceFile(dotExport);
114	        } else if (typeof dotExport === 'object') {
115	          const hasMatch = Object.entries(dotExport).some(([key, value]) => {
116	            if (key === 'types' || key === 'development' || key.startsWith('@'))
117	              return false;
118	            return typeof value === 'string' && isPathSourceFile(value);
119	          });
120	          return !hasMatch;
121	        }
122	      }
123	    }
124	
125	    const buildPaths = ['main', 'module'];
126	    for (const field of buildPaths) {
127	      if (packageJson[field] && isPathSourceFile(packageJson[field])) {
128	        return false;
129	      }
130	    }
131	    return true;
132	  }
133	
134	  // Handle outDir
135	  const outDir = tsConfig.options.outDir;
136	  let resolvedOutDir: string | undefined;
137	  if (outDir) {
138	    const potentialOutDir = resolve(workspaceRoot, resolvedProjectPath, outDir);
139	    const relativePath = relative(projectAbsolutePath, potentialOutDir);
140	
141	    // If outDir is outside project root: buildable
142	    if (relativePath.startsWith('..')) {
143	      return true;
144	    }
145	
146	    // If outDir is inside project root, then we should check entry points
147	    if (!relativePath.startsWith('..')) {
148	      resolvedOutDir = potentialOutDir;
149	    }
150	  }
151	
152	  const isPathSourceFile = (path: string): boolean => {
153	    const normalizedPath = isAbsolute(path)
154	      ? resolve(workspaceRoot, path.startsWith('/') ? path.slice(1) : path)
155	      : resolve(workspaceRoot, resolvedProjectPath, path);
156	
157	    if (resolvedOutDir) {
158	      // If the path is within the outDir, we assume it's not a source file.
159	      const relativePath = relative(resolvedOutDir, normalizedPath);
160	      if (!relativePath.startsWith('..')) {
161	        return false;
162	      }
163	    }
164	
165	    // If no include patterns, TypeScript includes all TS files by default
166	    const include = tsConfig.raw?.include;
167	    if (!include || !Array.isArray(include)) {
168	      const ext = extname(path);
169	      const tsExtensions = ['.ts', '.tsx', '.cts', '.mts'];
170	      if (tsExtensions.includes(ext)) {
171	        return true;
172	      }
173	      // If include is not defined and it's not a TS file, assume it's not a source file
174	      return false;
175	    }
176	
177	    const projectAbsolutePath = resolve(workspaceRoot, resolvedProjectPath);
178	    const relativeToProject = relative(projectAbsolutePath, normalizedPath);
179	
180	    for (const pattern of include) {
181	      if (picomatch(pattern)(relativeToProject)) {
182	        return true;
183	      }
184	    }
185	
186	    return false;
187	  };
188	
189	  const containsInvalidPath = (
190	    value: string | Record<string, string>
191	  ): boolean => {
192	    if (typeof value === 'string') {
193	      return isPathSourceFile(value);
194	    } else if (typeof value === 'object') {
195	      return Object.entries(value).some(([currentKey, subValue]) => {
196	        // Skip types and development conditions
197	        if (
198	          currentKey === 'types' ||
199	          currentKey === 'development' ||
200	          currentKey.startsWith('@')
201	        ) {
202	          return false;
203	        }
204	        if (typeof subValue === 'string') {
205	          return isPathSourceFile(subValue);
206	        }
207	        return false;
208	      });
209	    }
210	    return false;
211	  };
212	
213	  const exports = packageJson?.exports;
214	
215	  // Check the `.` export if `exports` is defined.
216	  if (exports) {
217	    if (typeof exports === 'string') {
218	      return !isPathSourceFile(exports);
219	    }
220	    if (typeof exports === 'object' && '.' in exports) {
221	      return !containsInvalidPath(exports['.']);
222	    }
