21	/**
22	 * Allow uses that use incremental builds to run `nx watch-deps` to continuously build all dependencies.
23	 */
24	export function addBuildAndWatchDepsTargets(
25	  workspaceRoot: string,
26	  projectRoot: string,
27	  targets: Record<string, TargetConfiguration>,
28	  options: { buildDepsTargetName?: string; watchDepsTargetName?: string },
29	  pmc: PackageManagerCommands
30	): void {
31	  let projectName: string;
32	
33	  const projectJsonPath = join(workspaceRoot, projectRoot, 'project.json');
34	  const packageJsonPath = join(workspaceRoot, projectRoot, 'package.json');
35	
36	  if (existsSync(projectJsonPath)) {
37	    const projectJson = readJsonFile(projectJsonPath);
38	    projectName = projectJson.name;
39	  } else if (existsSync(packageJsonPath)) {
40	    const packageJson = readJsonFile(packageJsonPath);
41	    projectName = packageJson.nx?.name ?? packageJson.name;
42	  }
43	
44	  if (!projectName) return;
45	
46	  if (projectName) {
47	    const buildDepsTargetName = options.buildDepsTargetName ?? 'build-deps';
48	    targets[buildDepsTargetName] = {
49	      dependsOn: ['^build'],
50	    };
51	    targets[options.watchDepsTargetName ?? 'watch-deps'] = {
52	      continuous: true,
53	      dependsOn: [buildDepsTargetName],
54	      command: `${pmc.exec} nx watch --projects ${projectName} --includeDependentProjects -- ${pmc.exec} nx ${buildDepsTargetName} ${projectName}`,
55	    };
56	  }
57	}
