59	export function isValidPackageJsonBuildConfig(
60	  tsConfig: ParsedTsconfigData,
61	  workspaceRoot: string,
62	  projectRoot: string
63	): boolean {
64	  const resolvedProjectPath = isAbsolute(projectRoot)
65	    ? relative(workspaceRoot, projectRoot)
66	    : projectRoot;
67	  const projectAbsolutePath = resolve(workspaceRoot, resolvedProjectPath);
68	  const packageJsonPath = join(projectAbsolutePath, 'package.json');
69	
70	  if (!existsSync(packageJsonPath)) {
71	    // If the package.json file does not exist.
72	    // Assume it's valid because it would be using `project.json` instead.
73	    return true;
74	  }
75	
76	  const packageJson = readJsonFile<PackageJson>(packageJsonPath);
77	
78	  // Check entry points against outFile (has precedence over outDir)
79	  if (tsConfig.options.outFile) {
80	    return isAnyEntryPointPointingToOutFile(
81	      packageJson,
82	      tsConfig,
83	      projectAbsolutePath,
84	      workspaceRoot
85	    );
86	  }
87	
88	  // Check entry points against outDir
89	  const outDir = tsConfig.options.outDir;
90	  if (outDir) {
91	    return isAnyEntryPointPointingToOutDir(
92	      packageJson,
93	      outDir,
94	      workspaceRoot,
95	      projectAbsolutePath
96	    );
97	  }
98	
99	  // Check entry points against include patterns
100	  return isAnyEntryPointPointingToNonIncludedFiles(
101	    packageJson,
102	    tsConfig,
103	    workspaceRoot,
104	    projectAbsolutePath
105	  );
106	}
