110	function isAnyEntryPointPointingToOutFile(
111	  packageJson: PackageJson,
112	  tsConfig: ParsedTsconfigData,
113	  projectAbsolutePath: string,
114	  workspaceRoot: string
115	): boolean {
116	  const outFile = resolve(projectAbsolutePath, tsConfig.options.outFile);
117	  const relativeToProject = relative(projectAbsolutePath, outFile);
118	
119	  // If outFile is outside project root: buildable
120	  if (relativeToProject.startsWith('..')) {
121	    return true;
122	  }
123	
124	  // If outFile is inside project root: check if entry points point to outFile
125	  const isPathPointingToOutputFile = (path: string): boolean => {
126	    return normalizePath(path, workspaceRoot, projectAbsolutePath) === outFile;
127	  };
128	
129	  const exports = packageJson.exports;
130	  if (!exports) {
131	    // If any entry point points to the outFile, or if no entry points are
132	    // defined (Node.js falls back to `./index.js`), then it's buildable
133	    return (
134	      packageJsonLegacyEntryPoints.some(
135	        (field) =>
136	          packageJson[field] && isPathPointingToOutputFile(packageJson[field])
137	      ) || packageJsonLegacyEntryPoints.every((field) => !packageJson[field])
138	    );
139	  }
140	
141	  if (typeof exports === 'string') {
142	    return isPathPointingToOutputFile(exports);
143	  }
144	
145	  const isExportsEntryPointingToOutFile = (
146	    value: string | Record<string, string>
147	  ): boolean => {
148	    if (typeof value === 'string') {
149	      return isPathPointingToOutputFile(value);
150	    }
151	
152	    if (typeof value === 'object') {
153	      return Object.values(value).some(
